def esc(value):
    return html.escape(str(value), quote=True)

def wa(message):
    return "https://wa.me/5516999999999?text=" + quote(message)

def img(site, size=1400):
    return f"../../assets/images/{site['slug']}.jpg"

def link(site):
    return wa(f"Olá! Vi o site da {site['name']} e gostaria de {site['cta'].lower()}.")

def section_services(s):
    cards = "".join(f'<article class="service-card reveal"><span class="service-index">{i:02d}</span><h3>{esc(item[0])}</h3><p>{esc(item[1])}</p>{"<strong>"+esc(item[2])+"</strong>" if len(item)>2 else ""}</article>' for i,item in enumerate(s['services'],1))
    return f'<section class="section services" id="servicos"><div class="section-heading reveal"><p class="eyebrow">{esc(COPY[s["slug"]][1])}</p><h2>{esc(HEADINGS[s["slug"]][0])}.</h2><p>{esc(COPY[s["slug"]][2])}</p></div><div class="service-grid">{cards}</div></section>'

def section_about(s):
    stats = "".join(f'<div><strong>{esc(a)}</strong><span>{esc(b)}</span></div>' for a,b in s['stats'])
    return f'<section class="section about" id="sobre"><div class="about-mark reveal" style="--mark-len:{len(s["name"].split()[0])}">{esc(s["name"].split()[0])}<span>●</span></div><div class="about-copy reveal"><p class="eyebrow">Nossa essência</p><h2>{esc(s["highlight"])}</h2><p>{esc(s["about"])}</p><div class="stats">{stats}</div></div></section>'

