def page_js(s):
    js = "// Page-specific behavior for " + s['name'] + "\n"
    if s['slug']=='solar-energy':
        js += '''const bill = document.querySelector('#bill');
const formatBRL = value => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(value);
function simulate(){const value=Math.max(0,Number(bill.value)||0);const month=value*.8;document.querySelector('[data-sim="month"]').textContent=formatBRL(month);document.querySelector('[data-sim="year"]').textContent=formatBRL(month*12);document.querySelector('[data-sim="long"]').textContent=formatBRL(month*12*25)}
bill.addEventListener('input',simulate);simulate();
'''
    elif s['slug'] in ('auto-detailing','aesthetic-clinic','petshop','construction'):
        js += '''const comparison=document.querySelector('.compare-box');const slider=comparison.querySelector('input');slider.addEventListener('input',()=>comparison.style.setProperty('--pos',slider.value+'%'));
'''
    elif s['slug']=='restaurant':
        js += '''const menu=document.querySelector('.menu-dialog');document.querySelector('[data-menu-open]').addEventListener('click',()=>menu.showModal());document.querySelector('[data-menu-close]').addEventListener('click',()=>menu.close());menu.addEventListener('click',event=>{if(event.target===menu)menu.close()});
'''
    elif s['slug']=='photographer':
        js += '''const lightbox=document.querySelector('.lightbox');document.querySelectorAll('[data-lightbox] img').forEach(photo=>{photo.tabIndex=0;photo.addEventListener('click',()=>{lightbox.querySelector('img').src=photo.src;lightbox.querySelector('img').alt=photo.alt;lightbox.showModal()});photo.addEventListener('keydown',event=>{if(event.key==='Enter')photo.click()})});document.querySelector('[data-lightbox-close]').addEventListener('click',()=>lightbox.close());lightbox.addEventListener('click',event=>{if(event.target===lightbox)lightbox.close()});
'''
    elif s['slug']=='school':
        js += '''const target=new Date();target.setDate(target.getDate()+21);const counter=document.querySelector('[data-countdown]');function updateCountdown(){const days=Math.max(0,Math.ceil((target-new Date())/86400000));counter.textContent=days+' dias'}updateCountdown();setInterval(updateCountdown,3600000);
'''
    else:
        js += "// Navigation, scroll reveals and form handling are in assets/js/site.js.\n"
    return js

